                <li><div class="fair-top"><span>Jonah Park</span><span>172h</span></div><div class="fair-bar"><i class="b-jonah"></i></div></li>
                <li><div class="fair-top"><span>Mei Chen</span><span>162h</span></div><div class="fair-bar"><i class="b-mei"></i></div></li>
                <li><div class="fair-top"><span>Tomás Leal</span><span>169h</span></div><div class="fair-bar"><i class="b-tomas"></i></div></li>
              </ul>
