cd "$RUN/work" && sed -i '' 's/<small>On-call hours · Oct<\/small>/<small>Hours in October<\/small>/' index.html && Q=/tmp/rotaline-qa && cat > $Q/harness.html <<EOF
<!doctype html><html><body style="margin:0;font:14px monospace">
<pre id="out" style="margin:0;padding:8px;background:#ff0;height:220px;overflow:hidden"></pre>
<iframe id="f" src="file://$PWD/index.html" width="390" height="900" style="border:0;display:block"></iframe>
<script>
var out=document.getElementById('out');function log(m){out.textContent+=m+'\n';}
var f=document.getElementById('f');
f.onload=function(){
 try{
  var w=f.contentWindow,d=w.document;
  log('scrollWidth='+d.documentElement.scrollWidth+' clientWidth='+d.documentElement.clientWidth);
  // overflow offenders
  var bad=[];d.querySelectorAll('body *').forEach(function(el){var r=el.getBoundingClientRect();if(r.right>391&&r.width>0&&getComputedStyle(el).position!=='fixed')bad.push(el.tagName+'.'+el.className)});
  log('overflowing: '+bad.slice(0,6).join(', '));
  d.getElementById('billing-annual').click();
  log('team='+d.querySelector('#plan-team').closest('.plan').querySelector('.price-amount').textContent+' biz='+d.querySelector('#plan-business').closest('.plan').querySelector('.price-amount').textContent+' note='+d.querySelector('#plan-team').closest('.plan').querySelector('.price-note').textContent);
  log('live='+d.getElementById('billing-status').textContent);
  d.getElementById('billing-monthly').click();
  log('back team='+d.querySelector('#plan-team').closest('.plan').querySelector('.price-amount').textContent);
  var t=d.querySelector('.nav-toggle'); t.click();
  log('menu expanded='+t.getAttribute('aria-expanded')+' visible='+(d.getElementById('mobile-nav').offsetHeight>0)+' focus='+d.activeElement.textContent);
  d.dispatchEvent(new w.KeyboardEvent('keydown',{key:'Escape'}));
  log('after esc expanded='+t.getAttribute('aria-expanded')+' focus on toggle='+(d.activeElement===t));
  var form=d.getElementById('signup-form'); form.requestSubmit();
  log('empty error='+d.getElementById('signup-error-text').textContent+' invalid='+d.getElementById('signup-email').getAttribute('aria-invalid'));
  d.getElementById('signup-email').value='bad@x'; form.requestSubmit();
  log('bad error='+d.getElementById('signup-error-text').textContent);
  d.getElementById('signup-email').value='dana@plinth.io'; form.requestSubmit();
  setTimeout(function(){log('success hidden='+d.getElementById('signup-success').hidden+' text='+d.getElementById('signup-success-text').textContent);
    t.click(); w.scrollTo(0,0);},900);
 }catch(e){log('ERR '+e)}
};
</script></body></html>
EOF
